Download once and commit into terminal/web/: https://cdn.jsdelivr.net/npm/world-atlas@2.0.2/countries-110m.json (107,761 B, gzip 38,495; sha256 2516c915...94eee8), land-110m.json (55,207 B, gzip 20,722), countries-50m.json (756,420 B, gzip 229,996; sha256 04342cdc...502394), land-50m.json (545,534 B, gzip 169,541). unpkg.com/world-atlas@2.0.2/land-110m.json is byte-identical. Each countries-*.json has objects 'countries' and 'land'. To also work from file://, wrap as a script (window.WORLD110=<json>;) and load with <script src>. Decode, no library:
function topoArcs(t){const T=t.transform,sx=T?T.scale[0]:1,sy=T?T.scale[1]:1,tx=T?T.translate[0]:0,ty=T?T.translate[1]:0;return t.arcs.map(a=>{let x=0,y=0;return a.map(p=>{x+=p[0];y+=p[1];return[x*sx+tx,y*sy+ty];});});}
function topoPolys(t,name,arcs){arcs=arcs||topoArcs(t);const out=[];const ring=ids=>{const r=[];for(const i of ids){const a=i<0?arcs[~i]:arcs[i],n=a.length;for(let k=r.length?1:0;k<n;k++)r.push(i<0?a[n-1-k]:a[k]);}return r;};(function walk(g){if(g.type==='GeometryCollection')g.geometries.forEach(walk);else if(g.type==='Polygon')out.push({id:g.id,name:g.properties&&g.properties.name,rings:g.arcs.map(ring)});else if(g.type==='MultiPolygon')g.arcs.forEach(p=>out.push({id:g.id,name:g.properties&&g.properties.name,rings:p.map(ring)}));})(t.objects[name]);return out;}
function topoBorders(t,name,arcs){arcs=arcs||topoArcs(t);const use=new Map();t.objects[name].geometries.forEach((g,gi)=>{(function f(a){if(typeof a==='number'){const k=a<0?~a:a;if(!use.has(k))use.set(k,new Set());use.get(k).add(gi);}else if(a)a.forEach(f);})(g.arcs);});const out=[];use.forEach((s,k)=>{if(s.size>1)out.push(arcs[k]);});return out;}
Fill topoPolys(t,'land') with the 'evenodd' rule; stroke topoBorders(t,'countries') for interior borders only.
